import{_ as t,o,c as a,a2 as i}from"./chunks/framework.gtmkOXzY.js";const g=JSON.parse('{"title":"Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"ms-flightsim/configuration.md","filePath":"ms-flightsim/configuration.md","lastUpdated":null}'),d={name:"ms-flightsim/configuration.md"};function s(n,e,r,c,l,h){return o(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h1><p>Everything is set in <code>config.lua</code>, but <strong>your own changes belong in <code>config_overrides.lua</code></strong>, which updates never replace. Most day-to-day settings (jobs on/off, pay, aircraft, airports, zones) can also be changed live in <code>/adminps</code> without touching a file.</p><h2 id="where-to-put-your-changes" tabindex="-1">Where to put your changes <a class="header-anchor" href="#where-to-put-your-changes" aria-label="Permalink to &quot;Where to put your changes&quot;">​</a></h2><ol><li><p>Rename <code>config_overrides.lua.example</code> to <code>config_overrides.lua</code>.</p></li><li><p>Set single fields there, one per line. Never copy a whole table, or you&#39;ll miss new keys in future updates.</p><div class="language-lua vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">lua</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Config.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">PilotAuthorization</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">enabled</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> false</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Config.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">GroundServices</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">requireJob</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Config.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ATCScope</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pilotsSeeTraffic</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span></span></code></pre></div></li><li><p>Restart MS_FlightSim. The overrides load after <code>config.lua</code>, so your values win.</p></li></ol><div class="warning custom-block"><p class="custom-block-title">Exceptions: money and language</p><p><code>Config.Payouts</code>, <code>Config.Prices</code> and <code>Config.Language</code> are applied while <code>config.lua</code> itself loads, so setting them in <code>config_overrides.lua</code> has no effect. Change them in <code>config.lua</code>, or raise or lower all pay with the <strong>Salaries</strong> dial in <code>/adminps</code>. See <a href="./economy">Economy</a> and <a href="./languages">Languages</a>, and re-apply these edits after an update.</p></div><p>Other update-safe files work the same way:</p><table tabindex="0"><thead><tr><th>File</th><th>For</th></tr></thead><tbody><tr><td><code>html/hud-config-overrides.js</code></td><td>HUD defaults</td></tr><tr><td><code>locales/zz_overrides.lua</code></td><td>Changing single translation strings</td></tr><tr><td><code>config_additions.lua</code></td><td>Not a settings file: a dated list of every new setting per release, for owners who edit <code>config.lua</code> directly</td></tr></tbody></table><h2 id="pilot-job-or-open-access" tabindex="-1">Pilot job or open access <a class="header-anchor" href="#pilot-job-or-open-access" aria-label="Permalink to &quot;Pilot job or open access&quot;">​</a></h2><p><code>Config.PilotAuthorization.enabled</code> decides who can fly jobs.</p><table tabindex="0"><thead><tr><th>Value</th><th>Behaviour</th></tr></thead><tbody><tr><td><code>true</code> (default)</td><td>Only players with the pilot job (<code>/setjob &lt;id&gt; pilot 0</code>) can take flight jobs. Others are told <em>&quot;Only licensed pilots can accept aviation contracts.&quot;</em></td></tr><tr><td><code>false</code></td><td><strong>Open access</strong>: no <code>/setjob</code> needed. Anyone can train at the NPC, earn their licence and take jobs. Licences and ranks still apply — those are earned by flying</td></tr></tbody></table><p>The server console prints which mode is active on every start.</p><h2 id="settings-owners-change-most" tabindex="-1">Settings owners change most <a class="header-anchor" href="#settings-owners-change-most" aria-label="Permalink to &quot;Settings owners change most&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>Config.PilotAuthorization.pilotJob</code></td><td><code>&#39;pilot&#39;</code></td><td>Job name used when the pilot job is required</td></tr><tr><td><code>Config.PilotAuthorization.captainGrade</code></td><td><code>3</code></td><td>Pilot-job grade that unlocks the Company tab (hire, fire, fund). Set it to your top grade</td></tr><tr><td><code>Config.Language</code></td><td><code>&#39;en&#39;</code></td><td><code>en</code>, <code>cs</code>, <code>de</code>, <code>es</code>, <code>fr</code>, <code>pl</code>, <code>ro</code> or <code>ru</code> — set it in <code>config.lua</code></td></tr><tr><td><code>Config.Framework</code></td><td><code>&#39;auto&#39;</code></td><td>Force <code>&#39;qbox&#39;</code>, <code>&#39;qbcore&#39;</code> or <code>&#39;esx&#39;</code> if detection picks the wrong one</td></tr><tr><td><code>Config.Features</code></td><td>all on</td><td>Switch off individual missions or systems (TCAS, TAWS, wind, autoland and more)</td></tr><tr><td><code>Config.Payouts</code></td><td></td><td>Economy Control Panel: global pay multiplier, company cut, rank bonus and pay per job — edit in <code>config.lua</code></td></tr><tr><td><code>Config.Prices</code></td><td></td><td>Aircraft price multiplier, rental deposit, sell-back rate, training and service fees — edit in <code>config.lua</code></td></tr><tr><td><code>Config.GroundServices.requireJob</code></td><td><code>false</code></td><td><code>true</code> limits the ground-services job to the <code>groundcrew</code> job</td></tr><tr><td><code>Config.AITraffic.groundOnly</code></td><td><code>true</code></td><td>AI aircraft stay parked at stands. <code>false</code> enables flying AI (beta)</td></tr><tr><td><code>Config.ATCScope.pilotsSeeTraffic</code></td><td><code>false</code></td><td>Whether pilots, not only controllers, see traffic on their radar</td></tr><tr><td><code>Config.Performance</code></td><td></td><td>Entity budgets for busy servers (see <a href="./performance">Performance</a>)</td></tr><tr><td><code>Config.Debug</code></td><td><code>false</code></td><td>Keep <code>false</code> on a live server: <code>true</code> skips the pilot-job, rank and rating checks</td></tr></tbody></table><h2 id="economy" tabindex="-1">Economy <a class="header-anchor" href="#economy" aria-label="Permalink to &quot;Economy&quot;">​</a></h2><p><code>Config.Payouts</code> and <code>Config.Prices</code> at the top of <code>config.lua</code> are the single place for money. The <code>/adminps</code> <strong>Salaries</strong> tab adds presets (Legacy, Low, Standard, High) and a gauge that shows whether your pay sits in a healthy band.</p><p>Default fees: plane training $55,000, helicopter training $45,000, theory exam $1,500, Safety Refresher $20,000, fuel $8/gal, repair $10/point, paint $5,000.</p>`,16)])])}const u=t(d,[["render",s]]);export{g as __pageData,u as default};
